WITH latest_match AS (SELECT s.*, latest.transaction_txn_time FROM accounts s JOIN LATERAL (SELECT c.txn_time AS transaction_txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT status, DATE_TRUNC('WEEK', opened_date) AS week_start, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'SAVINGS' THEN 1 END), 0), 2) AS balance_per_savings, COUNT(*) FILTER (WHERE account_type = 'CREDIT') AS credit_rows, COUNT(*) FILTER (WHERE status = 'FROZEN') AS frozen_rows, PERCENTILE_APPROX(balance, 0.5) AS balance_p50, MIN(transaction_txn_time) AS first_seen FROM latest_match GROUP BY status, DATE_TRUNC('WEEK', opened_date) HAVING ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'SAVINGS' THEN 1 END), 0), 2) < 1000000 ORDER BY credit_rows
